	public static function get_svg( $icon ) {
		if ( strpos( $icon, '<svg' ) !== false ) {
			return $icon;
		}
		return self::get( $icon );
	}

	/**
	 * Output an icon directly to the page
	 * 
	 * @param string $icon The icon name or SVG markup to output
	 * @return void
	 */
	public static function output( $icon ) {
		echo self::get_svg( $icon );
	}
